function flipPrefix(word: string, ch: string): string {
  const k = word.indexOf(ch);
  if (k === -1) return word;
  const a = word.split("");
  for (let i = 0, j = k; i < j; i++, j--) [a[i], a[j]] = [a[j], a[i]];
  return a.join("");
}

