class Solution:
    def flipPrefix(self, word: str, ch: str) -> str:
        k = word.find(ch)
        a = list(word)
        i, j = 0, k
        while i < j:
            a[i], a[j] = a[j], a[i]
            i += 1
            j -= 1
        return "".join(a)

